<?php
namespace App\Services;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\Http;class NominatimService{public function geocode(string $address):?array{return Cache::remember('nominatim:'.sha1($address),now()->addMinutes(30),function()use($address){try{$r=Http::timeout(8)->withHeaders(['User-Agent'=>'HeatAlert/1.0'])->get('https://nominatim.openstreetmap.org/search',['q'=>$address,'format'=>'json','limit'=>1]);$d=$r->json('0');if(!$r->successful()||!is_array($d)||!isset($d['lat'],$d['lon']))return null;return ['latitude'=>(float)$d['lat'],'longitude'=>(float)$d['lon'],'display_name'=>$d['display_name']??$address];}catch(\Throwable){return null;}});}}
